import React from "react";

export default function MessageList({ messages = [] }){
  return (
    <div>
      {messages.map((m, i) => (
        <div key={i} className={`msg ${m.from}`}>
          <div className="bubble">
            {m.text}
          </div>
        </div>
      ))}
    </div>
  );
}
